import base64
from pathlib import Path
p=Path('/mnt/data/habalance_demo')
photo=base64.b64encode((p/'valmentaja.jpg').read_bytes()).decode()
logo=base64.b64encode((p/'logo.jpg').read_bytes()).decode()
html='''<!doctype html><html lang="fi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#f7f5ef"><title>HaBalance – Läsnäoloa arkeesi</title><style>
*{box-sizing:border-box}body{margin:0;background:#e9ede5;color:#253f31;font-family:system-ui,-apple-system,Arial,sans-serif}.app{max-width:460px;margin:auto;min-height:100dvh;background:#faf9f5;padding:22px 20px 100px}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.logo{display:block;width:min(230px,62vw);height:auto;mix-blend-mode:multiply}.small{font-size:11px;letter-spacing:2px;color:#708274}.tag{font-size:11px;background:#e6ebe3;border-radius:30px;padding:8px 12px}.hero{position:relative;height:310px;border-radius:22px;overflow:hidden;background:#d6dfd1}.hero img{height:100%;width:100%;object-fit:cover;object-position:73% 39%}.shade{position:absolute;inset:0;background:linear-gradient(90deg,rgba(244,242,232,.98) 0%,rgba(244,242,232,.76) 44%,transparent 85%)}.hero-copy{position:absolute;top:24px;left:18px;width:57%}h1,h2{font-family:Georgia,serif;font-weight:500}h1{font-size:30px;line-height:1.12;margin:0 0 12px}h2{font-size:23px;margin:24px 0 12px}p{line-height:1.5}.hero p{font-size:13px}.btn{background:#315e42;color:white;border:0;border-radius:14px;padding:14px 16px;font-weight:600;font-size:14px;cursor:pointer}.btn.alt{background:#e4ece2;color:#315e42}.btn.full{width:100%}.hero .btn{font-size:12px;padding:11px}.moods{display:grid;grid-template-columns:1fr 1fr;gap:10px}.mood{background:#f0f1eb;border:2px solid transparent;border-radius:15px;padding:18px 8px;text-align:center;color:#31543e;cursor:pointer}.mood.active{border-color:#658a70;background:#e2ecdf}.mood span{display:block;font-size:23px;margin-bottom:7px}.recommend{margin-top:20px;background:#e3ecdf;border-radius:20px;padding:20px}.recommend h2{margin:5px 0}.muted{color:#6c7b6e;font-size:13px}.nav{position:fixed;bottom:0;left:50%;transform:translateX(-50%);max-width:460px;width:100%;display:grid;grid-template-columns:repeat(4,1fr);background:#faf9f5;border-top:1px solid #dce4d9;padding:11px 6px max(12px,env(safe-area-inset-bottom));z-index:5}.nav button{border:0;background:none;color:#788b7a;font-size:11px;cursor:pointer}.nav button.active{color:#2f5c40;font-weight:bold}.nav i{display:block;font-size:22px;font-style:normal;margin-bottom:4px}.page{display:none}.page.active{display:block}.tile{display:flex;justify-content:space-between;align-items:center;background:#eff2eb;border-radius:17px;padding:17px;margin:12px 0;cursor:pointer}.tile strong{display:block}.coachphoto{width:100%;height:330px;object-fit:cover;object-position:80% 35%;border-radius:20px}.panel{background:#e7eee3;padding:22px;border-radius:20px;margin:18px 0}.step{font-family:Georgia,serif;font-size:24px;line-height:1.4;text-align:center;padding:25px 0}.progress{display:flex;gap:8px;justify-content:center}.dot{height:7px;width:40px;border-radius:10px;background:#cbd9c9}.dot.on{background:#477454}.chat{display:flex;flex-direction:column;gap:12px;min-height:300px}.bubble{padding:13px 15px;border-radius:17px;max-width:87%;line-height:1.5;font-size:14px;background:#ecf0e9;align-self:flex-start}.bubble.user{background:#d7e8d7;align-self:flex-end}.composer{display:flex;gap:7px;margin-top:15px}.composer input{flex:1;min-width:0;border:1px solid #cfdace;border-radius:13px;padding:14px;font-size:14px}.composer .btn{padding:12px}.foot{font-size:11px;color:#7a897b;margin-top:12px}button:focus-visible,input:focus-visible{outline:3px solid #86aa8a;outline-offset:2px}
</style></head><body><main class="app"><header><div><img class="logo" src="data:image/jpeg;base64,LOGO" alt="HaBalance-logo"><div class="small">LÄSNÄOLOA ARKEESI</div></div><div class="tag">DEMO</div></header>
<section class="page active" id="home"><div class="hero"><img src="data:image/jpeg;base64,PHOTO" alt="HaBalancen valmentaja"><div class="shade"></div><div class="hero-copy"><h1>Tervetuloa tähän hetkeen.</h1><p>Pienikin pysähdys voi tuoda rauhaa kiireiseen arkeen.</p><button class="btn" onclick="show('coach')">▶ Valmentajan tervehdys</button></div></div><h2>Miltä sinusta tuntuu juuri nyt?</h2><div class="moods"><button class="mood active" data-mood="kiire" onclick="mood(this)"><span>◷</span>Kiireiseltä</button><button class="mood" data-mood="stressi" onclick="mood(this)"><span>☁</span>Kuormittuneelta</button><button class="mood" data-mood="väsynyt" onclick="mood(this)"><span>☾</span>Väsyneeltä</button><button class="mood" data-mood="hyvä" onclick="mood(this)"><span>☀</span>Tasapainoiselta</button></div><div class="recommend"><div class="muted">SUOSITUS SINULLE</div><h2 id="rec">Hengähdys kiireen keskellä</h2><p class="muted">Pieni hetki vain sinua varten.</p><button class="btn full" onclick="start(selected)">Aloita harjoitus →</button></div></section>
<section class="page" id="coach"><img class="coachphoto" src="data:image/jpeg;base64,PHOTO" alt="HaBalancen valmentaja"><h2>Oma läsnäolovalmentajasi</h2><p>Hei! Tervetuloa HaBalanceen. Täällä saat pysähtyä omassa tahdissasi. Harjoitellaan yhdessä pieniä läsnäolon hetkiä keskellä tavallista arkea.</p><div class="panel"><strong>Valmentajan videotervehdys</strong><p class="muted">Tähän lisätään myöhemmin valmentajan oma video ja ääni.</p></div><button class="btn full" onclick="show('chat')">Keskustele valmentajan kanssa</button></section>
<section class="page" id="library"><h2>Harjoitukset</h2><p class="muted">Valitse juuri tähän hetkeen sopiva harjoitus.</p><div id="exerciseList"></div></section>
<section class="page" id="exercise"><div class="muted" id="exdur"></div><h2 id="extitle"></h2><div class="panel"><div class="muted" id="exstep"></div><div class="step" id="extext"></div><div class="progress" id="dots"></div></div><button class="btn full" onclick="nextStep()" id="nextbtn">Jatka rauhassa →</button><p style="text-align:center"><button class="btn alt" onclick="show('home')">Palaa etusivulle</button></p></section>
<section class="page" id="done"><div class="panel" style="text-align:center;padding:50px 20px"><div style="font-size:50px">♡</div><h2>Hienoa, että pysähdyit.</h2><p>Voit palata tähän hetkeen milloin tahansa.</p><button class="btn" onclick="show('home')">Takaisin etusivulle</button></div></section>
<section class="page" id="chat"><h2>Jutellaan hetki</h2><p class="muted">Valmentajan esimerkkikeskustelu</p><div class="chat" id="messages"><div class="bubble">Hei, ihana kun olet täällä. Miten voisin auttaa sinua löytämään enemmän läsnäoloa tähän hetkeen?</div></div><form class="composer" onsubmit="send(event)"><input id="message" aria-label="Kirjoita viesti" placeholder="Kerro, mitä mielessäsi on..." required><button class="btn">➤</button></form><div class="foot">Demossa vastaukset ovat valmiiksi laadittuja, eivät tekoälyn tuottamia.</div></section>
</main><nav class="nav"><button data-page="home" class="active" onclick="show('home')"><i>⌂</i>Etusivu</button><button data-page="library" onclick="show('library')"><i>❀</i>Harjoitukset</button><button data-page="coach" onclick="show('coach')"><i>♡</i>Valmentaja</button><button data-page="chat" onclick="show('chat')"><i>☏</i>Keskustelu</button></nav><script>
const exercises=[{title:'Hengähdys kiireen keskellä',duration:'2 min',steps:['Tunne jalkapohjasi lattiaa vasten. Anna hartioidesi laskeutua.','Hengitä rauhallisesti sisään ja ulos kolme kertaa. Mitään ei tarvitse suorittaa.','Katso ympärillesi. Huomaa yksi asia, jonka näet. Olet tässä hetkessä.']},{title:'Palauta keskittyminen',duration:'3 min',steps:['Pysähdy hetkeksi ja huomaa hengityksesi.','Valitse yksi asia, johon keskityt seuraavaksi.','Anna muiden tehtävien odottaa. Yksi asia kerrallaan riittää.']},{title:'Lempeä palautuminen',duration:'5 min',steps:['Asetu mukavasti ja huomaa, miltä kehossasi tuntuu.','Hengitä luonnollisesti. Huomaa mahdollinen jännitys ilman tarvetta muuttaa sitä.','Anna itsellesi lupa olla tekemättä mitään juuri nyt.']}];let selected=0,idx=0,step=0;
function show(id){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===id));scrollTo(0,0)}
function mood(el){document.querySelectorAll('.mood').forEach(x=>x.classList.remove('active'));el.classList.add('active');selected=el.dataset.mood==='väsynyt'?2:el.dataset.mood==='hyvä'?1:0;document.getElementById('rec').textContent=exercises[selected].title}
function start(i){idx=i;step=0;renderExercise();show('exercise')}
function renderExercise(){const e=exercises[idx];document.getElementById('extitle').textContent=e.title;document.getElementById('exdur').textContent=e.duration+' · OHJATTU HARJOITUS';document.getElementById('exstep').textContent='VAIHE '+(step+1)+' / '+e.steps.length;document.getElementById('extext').textContent=e.steps[step];document.getElementById('dots').innerHTML=e.steps.map((_,i)=>'<div class="dot '+(i===step?'on':'')+'"></div>').join('');document.getElementById('nextbtn').textContent=step===e.steps.length-1?'Päätä harjoitus ✓':'Jatka rauhassa →'}
function nextStep(){if(step<exercises[idx].steps.length-1){step++;renderExercise()}else show('done')}
document.getElementById('exerciseList').innerHTML=exercises.map((e,i)=>'<div class="tile" role="button" tabindex="0" onclick="start('+i+')" onkeydown="if(event.key===\'Enter\')start('+i+')"><div><strong>'+e.title+'</strong><span class="muted">'+e.duration+' · Ohjattu harjoitus</span></div><span>▶</span></div>').join('');
function bubble(t,user){const el=document.createElement('div');el.className='bubble'+(user?' user':'');el.textContent=t;document.getElementById('messages').appendChild(el);el.scrollIntoView({behavior:'smooth',block:'nearest'})}
function send(ev){ev.preventDefault();const input=document.getElementById('message'),q=input.value.trim();if(!q)return;bubble(q,true);input.value='';let a=/kiire|stress|työ/i.test(q)?'Kiire voi tuntua sekä mielessä että kehossa. Kokeile pysähtyä hetkeksi ja tuntea jalkapohjasi lattiaa vasten. Hengitä rauhallisesti kolme kertaa.':/väs|uni|palaut/i.test(q)?'Kuulostaa siltä, että pieni palautumishetki voisi tehdä hyvää. Anna itsellesi lupa levätä hetki ilman tavoitteita.':'Kiitos kun kerroit. Mitä huomaat kehossasi juuri nyt? Voit pysähtyä sen tuntemuksen äärelle hetkeksi.';bubble(a,false)}
</script></body></html>'''.replace('PHOTO',photo).replace('LOGO',logo)
(p/'index.html').write_text(html,encoding='utf-8')
print((p/'index.html').stat().st_size)
